import { useId } from "react";

import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Brush, Eraser, Scissors, SwatchBook } from "lucide-react";

export default function Component() {
	const id = useId();

	const items = [
		{ value: "1", label: "Palette", Icon: SwatchBook, defaultChecked: true },
		{ value: "2", label: "Brush", Icon: Brush },
		{ value: "3", label: "Eraser", Icon: Eraser },
		{ value: "4", label: "Cut", Icon: Scissors },
	];

	return (
		<div className="grid grid-cols-2 gap-3">
			{items.map((item) => (
				<div
					key={`${id}-${item.value}`}
					className="border-input has-data-[state=checked]:border-primary/50 relative flex cursor-pointer flex-col gap-4 rounded-md border p-4 shadow-2xs outline-hidden"
				>
					<div className="flex justify-between gap-2">
						<Checkbox
							id={`${id}-${item.value}`}
							value={item.value}
							className="order-1 after:absolute after:inset-0"
							defaultChecked={item.defaultChecked}
						/>
						<item.Icon
							className="opacity-60"
							size={16}
							aria-hidden="true"
						/>
					</div>
					<Label htmlFor={`${id}-${item.value}`}>{item.label}</Label>
				</div>
			))}
		</div>
	);
}

"use client";

import React from "react";

import { cn } from "@/lib/utils";
import * as CheckboxPrimitive from "@radix-ui/react-checkbox";
import { Check } from "lucide-react";

const Checkbox = React.forwardRef<
	React.ElementRef<typeof CheckboxPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof CheckboxPrimitive.Root>
>(({ className, ...props }, ref) => (
	<CheckboxPrimitive.Root
		ref={ref}
		className={cn(
			"peer h-4 w-4 shrink-0 rounded-sm border border-primary ring-offset-background focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground",
			className
		)}
		{...props}
	>
		<CheckboxPrimitive.Indicator
			className={cn("flex items-center justify-center text-current")}
		>
			<Check className="h-4 w-4" />
		</CheckboxPrimitive.Indicator>
	</CheckboxPrimitive.Root>
));
Checkbox.displayName = CheckboxPrimitive.Root.displayName;

export { Checkbox };

"use client";

import React from "react";

import { cn } from "@/lib/utils";
import * as LabelPrimitive from "@radix-ui/react-label";
import { cva, type VariantProps } from "class-variance-authority";

const labelVariants = cva(
	"text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
);

const Label = React.forwardRef<
	React.ElementRef<typeof LabelPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof LabelPrimitive.Root> &
		VariantProps<typeof labelVariants>
>(({ className, ...props }, ref) => (
	<LabelPrimitive.Root
		ref={ref}
		className={cn(labelVariants(), className)}
		{...props}
	/>
));
Label.displayName = LabelPrimitive.Root.displayName;

export { Label };
